head.script:
scwin.onpageload = function() {
    scwin.code = [{
            "appCd": "CNG",
            "comCdDesc": "CNG",
            "rowStatus": "R"
        },
        {
            "appCd": "DND",
            "comCdDesc": "DND",
            "rowStatus": "R"
        },
        {
            "appCd": "DRO",
            "comCdDesc": "DRO",
            "rowStatus": "R"
        },
        {
            "appCd": "FLT",
            "comCdDesc": "LSE",
            "rowStatus": "R"
        },
        {
            "appCd": "TPR",
            "comCdDesc": "TPR",
            "rowStatus": "R"
        },
        {
            "appCd": "FES",
            "comCdDesc": "FES",
            "rowStatus": "R"
        },
        {
            "appCd": "TRS",
            "comCdDesc": "TRS",
            "rowStatus": "R"
        },
        {
            "appCd": "JOS",
            "comCdDesc": "CNG",
            "rowStatus": "R"
        },
        {
            "appCd": "LSE",
            "comCdDesc": "LSE",
            "rowStatus": "R"
        },
        {
            "appCd": "PSO",
            "comCdDesc": "MNR",
            "rowStatus": "R"
        },
        {
            "appCd": "FAR",
            "comCdDesc": "FINANCE ACCOUNT RECEIVABLE",
            "rowStatus": "R"
        },
        {
            "appCd": "FAP",
            "comCdDesc": "FINANCE ACCOUNT PAYABLE",
            "rowStatus": "R"
        }
    ];
    dlCode.setJSON(scwin.code);
    dlList.setJSON([{
        "appCd": "DND"
    }]);
};
scwin.onpageunload = function() {};
scwin.rowAdd_onclick = function() {
    dlList.insertRow(0);
    grdList.setCellReadOnly(0, "appCd", false);
    grdList.setCellReadOnly(0, "appCd2", false);
    var info = {
        inputType: "autoComplete",
        options: {
            "caseSensitive": "false",
            viewType: "icon",
            selectedData: "false",
            chooseOption: "true",
            chooseOptionLabel: "$blank"
            //,allowChar: "'a-zA-Z0-9'"
        },
        itemSet: {
            nodeset: "data:dlCode",
            label: "comCdDesc",
            value: "appCd"
        }
    }
    grdList.setCellInputType(0, "appCd2", info);
    grdList.setFocusedCell(0, "appCd", true);
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#G_grdList___autoComplete_0_appCd2_dynamic_autoComplete_0_1_input', 'key-sequence', {
        sequence: 'd'
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#input2', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'rowAdd').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'grdList_cell_0_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('G_'+$p.id+'grdList___autoComplete_0_appCd2_dynamic_autoComplete_0_1_itemTable').style.display == 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
